declare
  v_plan constant jsonb := $audit_plan${"generatedBy":"scripts/prod-open/sat-trim160-sql.ts","problems":[{"patch_id":"E1019-T001","problem_id":"829542e9-6519-4df6-bc6b-3cc5c712366a","from_version_id":"26ddcefe-53d2-4a36-a6c3-af97846496a2","expect":{"passage":"In late medieval English towns such as York and Chester, mystery plays were staged not by clergy but by craft guilds, each of which took responsibility for a single biblical episode. Performed on movable wagons that rolled from station to station through the streets, the cycles moved from the Creation to the Last Judgment over a single long day. Because most spectators could not read Latin scripture, these performances gave them a vivid, sequential account of sacred history in their own language. Scholars have often treated the plays mainly as teaching tools imposed from above, but recent research complicates that view. Guild records show that members spent their own money on costumes and stage effects, argued over which episodes they would be assigned, and sometimes chose episodes linked to their trade—the shipwrights, for instance, staged the building of Noah's ark. Such evidence suggests that the plays were not simply lessons handed to a passive public; they were also a way for townspeople to claim a place for themselves within the religious story they were helping to tell."},"set":{"passage":"In late medieval English towns such as York and Chester, mystery plays were staged not by clergy but by craft guilds, each of which took responsibility for a single biblical episode. Because most spectators could not read Latin scripture, these performances gave them a vivid, sequential account of sacred history in their own language. Scholars have often treated the plays mainly as teaching tools imposed from above, but recent research complicates that view. Guild records show that members spent their own money on costumes and stage effects, argued over which episodes they would be assigned, and sometimes chose episodes linked to their trade—the shipwrights, for instance, staged the building of Noah's ark. Such evidence suggests that the plays were not simply lessons handed to a passive public; they were also a way for townspeople to claim a place for themselves within the religious story they were helping to tell."},"render_check":{"ok":true,"renderer":"std-1","checkedAt":"2026-10-20T06:07:24.242Z","issues":[]},"audit_fix":{"source":"external_audit_2026-10-13","patch":"E1019-T001","fromVersionId":"26ddcefe-53d2-4a36-a6c3-af97846496a2","fromVersionNo":1}},{"patch_id":"E1019-T002","problem_id":"cabe66af-bc8e-4a61-9266-8b64ba2439a0","from_version_id":"285e8577-1065-4919-9270-1acd3a645b4f","expect":{"passage":"Listeners new to Indian classical music often assume that a raga performance is either strictly composed or entirely spontaneous. In fact, it is neither. A raga specifies a set of pitches, characteristic ascending and descending patterns, and certain phrases that must recur, and many of its intervals derive from simple whole-number frequency ratios, such as the 3:2 relationship that defines the perfect fifth. These constraints are fixed long before any musician sits down to play.\n\nYet within those limits, performers are expected to invent. In the slow opening section known as the alap, a sitarist may spend half an hour exploring a single raga, deciding moment by moment which pitch to linger on, how to bend toward the next, and when to introduce a signature phrase. Musicologist Martin Clayton has argued that this freedom is meaningful precisely because the boundaries are so precise: listeners recognize a performer's originality by hearing how inventively the musician moves while never stepping outside the raga's rules."},"set":{"passage":"Listeners new to Indian classical music often assume that a raga performance is either strictly composed or entirely spontaneous. In fact, it is neither. A raga specifies a set of pitches, characteristic ascending and descending patterns, and certain phrases that must recur, and many of its intervals derive from simple whole-number frequency ratios. These constraints are fixed long before any musician sits down to play.\n\nYet within those limits, performers are expected to invent. In the slow opening section known as the alap, a sitarist may spend half an hour exploring a single raga, deciding moment by moment which pitch to linger on, how to bend toward the next, and when to introduce a signature phrase. Musicologist Martin Clayton has argued that this freedom is meaningful precisely because the boundaries are so precise: listeners recognize a performer's originality by hearing how inventively the musician moves while never stepping outside the raga's rules."},"render_check":{"ok":true,"renderer":"std-1","checkedAt":"2026-10-20T06:07:24.243Z","issues":[]},"audit_fix":{"source":"external_audit_2026-10-13","patch":"E1019-T002","fromVersionId":"285e8577-1065-4919-9270-1acd3a645b4f","fromVersionNo":1}},{"patch_id":"E1019-T003","problem_id":"7957cf07-7d69-4e64-8c53-d93aec2dd657","from_version_id":"04423e5f-0f59-4c2d-a31c-430b189a1eb9","expect":{"passage":"For decades, scholars dated the Dead Sea Scrolls chiefly through paleography, comparing the shapes of letters in each manuscript with a sequence of scripts thought to have evolved gradually over time. A scroll whose scribe wrote a particular form of the letter aleph, for example, would be placed earlier or later in that sequence. Researcher Mladen Popović and colleagues have argued that this method, though valuable, rests on an assumption that every scribe of a given period wrote in roughly the same way. Using radiocarbon results from several scrolls together with computer analysis of ink traces, the team found that some manuscripts once assigned to the first century BCE were in fact copied decades earlier, and that two hands judged identical by eye differed in subtle stroke patterns. Popović's team does not propose abandoning letter-shape comparison; rather, they suggest that the traditional script sequence be recalibrated against physical evidence so that individual scribal habits are not mistaken for signs of a different era."},"set":{"passage":"For decades, scholars dated the Dead Sea Scrolls chiefly through paleography, comparing the shapes of letters in each manuscript with a sequence of scripts thought to have evolved gradually over time. A scroll whose scribe wrote a particular form of the letter aleph, for example, would be placed earlier or later in that sequence. Researcher Mladen Popović and colleagues have argued that this method, though valuable, rests on an assumption that every scribe of a given period wrote in roughly the same way. Using radiocarbon results from several scrolls together with computer analysis of ink traces, the team found that some manuscripts once assigned to the first century BCE were in fact copied decades earlier, and that two hands judged identical by eye differed in subtle stroke patterns. Popović's team does not propose abandoning letter-shape comparison; rather, they suggest that the traditional script sequence be recalibrated against physical evidence."},"render_check":{"ok":true,"renderer":"std-1","checkedAt":"2026-10-20T06:07:24.244Z","issues":[]},"audit_fix":{"source":"external_audit_2026-10-13","patch":"E1019-T003","fromVersionId":"04423e5f-0f59-4c2d-a31c-430b189a1eb9","fromVersionNo":1}},{"patch_id":"E1019-T004","problem_id":"9955b04a-fd58-46e2-8211-baffdd5a7ecc","from_version_id":"81164ccb-3190-4e24-ac35-0d234eea5a52","expect":{"passage":"The Peace of Westphalia, signed in 1648, is often credited with inventing the modern system of sovereign states, in which each government holds supreme authority within its own borders. Historian Andreas Osiander and others have questioned this view. They note that the treaties said little about sovereignty as an abstract principle; instead, they settled specific disputes over territory, religion, and the constitution of the Holy Roman Empire, and they even gave foreign powers such as Sweden and France the right to help guarantee the empire's internal arrangements. Such provisions hardly fit a model of fully independent states. Still, these scholars concede that the settlement mattered: by confirming that rulers could determine the official religion of their lands, it removed one of the main justifications for outside intervention and helped end a century of religious warfare. On this reading, Westphalia advanced the idea of sovereignty without establishing it, and the clear principle later attributed to it was largely built up by nineteenth- and twentieth-century writers looking back."},"set":{"passage":"The Peace of Westphalia, signed in 1648, is often credited with inventing the modern system of sovereign states, in which each government holds supreme authority within its own borders. Historian Andreas Osiander and others have questioned this view. They note that the treaties said little about sovereignty as an abstract principle; instead, they settled specific disputes over territory, religion, and the constitution of the Holy Roman Empire, and they even gave foreign powers such as Sweden and France the right to help guarantee the empire's internal arrangements. Still, these scholars concede that the settlement mattered: by confirming that rulers could determine the official religion of their lands, it removed one of the main justifications for outside intervention and helped end a century of religious warfare. On this reading, Westphalia advanced the idea of sovereignty without establishing it, and the clear principle later attributed to it was largely built up by nineteenth- and twentieth-century writers looking back."},"render_check":{"ok":true,"renderer":"std-1","checkedAt":"2026-10-20T06:07:24.244Z","issues":[]},"audit_fix":{"source":"external_audit_2026-10-13","patch":"E1019-T004","fromVersionId":"81164ccb-3190-4e24-ac35-0d234eea5a52","fromVersionNo":1}},{"patch_id":"E1019-T005","problem_id":"3f561501-398a-4ef0-b478-a6da114cd211","from_version_id":"2166ddb4-bd13-4d6f-be6e-c636684f35ec","expect":{"passage":"In the thirteenth century, a merchant traveling from Genoa to the fairs of Champagne faced a costly problem: carrying chests of silver coins across the Alps invited robbery, and coins minted in one city often had uncertain value in another. Genoese bankers addressed this by refining the bill of exchange, a written order in which a banker in one city promised that a partner in a distant city would pay the bearer a fixed sum in local currency. Historians have often celebrated the bill mainly as a safer way to move money. Yet the bankers' records suggest its larger effect lay elsewhere. Because payment came weeks after the bill was issued and in a different currency, the exchange rate written on the bill could quietly build in a charge for the delay. That let bankers earn what was in effect interest at a time when Church law condemned openly charging it, and it made lending over long distances both profitable and permissible."},"set":{"passage":"In the thirteenth century, a merchant traveling from Genoa to the fairs of Champagne faced a costly problem: carrying chests of silver coins across the Alps invited robbery, and coins minted in one city often had uncertain value in another. Genoese bankers addressed this by refining the bill of exchange, a written order in which a banker in one city promised that a partner in a distant city would pay the bearer a fixed sum in local currency. Historians have often celebrated the bill as a safer way to move money. Yet the bankers' records suggest its larger effect lay elsewhere. Because payment came weeks after the bill was issued and in a different currency, the exchange rate written on the bill could build in a charge for the delay. That let bankers earn what was in effect interest at a time when Church law condemned charging it, and it made lending over long distances both profitable and permissible."},"render_check":{"ok":true,"renderer":"std-1","checkedAt":"2026-10-20T06:07:24.244Z","issues":[]},"audit_fix":{"source":"external_audit_2026-10-13","patch":"E1019-T005","fromVersionId":"2166ddb4-bd13-4d6f-be6e-c636684f35ec","fromVersionNo":1}},{"patch_id":"E1019-T006","problem_id":"4f9809e4-8317-421e-86c8-f3e477f10c49","from_version_id":"5827c0e3-3255-450c-b593-36fd106f0880","expect":{"passage":"In the fifteenth and sixteenth centuries, tapestry workshops in Flemish cities such as Brussels and Arras supplied wall hangings to royal courts across Europe. Because a single large tapestry could take a team of weavers years to finish, workshop owners had strong reasons to guard the dyeing recipes and weaving techniques that set their products apart. Local guilds helped them do so: apprentices were bound to a master for several years, and guild rules barred trained weavers from leaving town to work for foreign rivals. Historians have often concluded that these restrictions kept Flemish skills from spreading. Economic historian Lien Vermeulen argues that the evidence suggests otherwise. Her review of workshop contracts shows that when wars and religious persecution pushed many weavers to flee to England, France, and Italy, foreign rulers quickly set up workshops staffed by these migrants, and the new workshops soon produced tapestries rivaling those of Flanders. In Vermeulen's view, guild rules slowed the movement of expertise only in peaceful times; they could not hold back skills carried by workers who had already decided to leave."},"set":{"passage":"In the fifteenth and sixteenth centuries, tapestry workshops in Flemish cities such as Brussels and Arras supplied wall hangings to royal courts across Europe. Because a single large tapestry could take a team of weavers years to finish, workshop owners had strong reasons to guard the dyeing recipes and weaving techniques that set their products apart. Local guilds helped them do so: apprentices were bound to a master for several years, and guild rules barred trained weavers from leaving town to work for foreign rivals. Historians have often concluded that these restrictions kept Flemish skills from spreading. Economic historian Lien Vermeulen argues that the evidence suggests otherwise. Her review of workshop contracts shows that when wars and religious persecution pushed many weavers to flee to England, France, and Italy, foreign rulers set up workshops staffed by these migrants, and the new workshops soon produced tapestries rivaling those of Flanders."},"render_check":{"ok":true,"renderer":"std-1","checkedAt":"2026-10-20T06:07:24.244Z","issues":[]},"audit_fix":{"source":"external_audit_2026-10-13","patch":"E1019-T006","fromVersionId":"5827c0e3-3255-450c-b593-36fd106f0880","fromVersionNo":1}},{"patch_id":"E1019-T007","problem_id":"ef9d1b60-b642-43dc-9c2e-3ecd85dadf14","from_version_id":"211fda92-c21d-44eb-8b79-f40fd8996fff","expect":{"passage":"When a glow-in-the-dark material absorbs light, some of its excited electrons end up in what physicists call a triplet state. Returning from this state to the ground state by emitting light is \"spin-forbidden,\" meaning the transition can happen only rarely, so the stored energy leaks out slowly as a faint glow that can last for seconds or even hours. For decades, chemists assumed that making this glow last longer simply required finding molecules whose triplet states were even more strongly forbidden from emitting. In practice, however, the longest-lasting commercial phosphors, such as strontium aluminate doped with europium and dysprosium, owe little to that strategy. In these materials, the dysprosium ions create defects that trap excited electrons before they reach any emitting state at all. Heat at room temperature then releases the trapped electrons a few at a time, and only after release do they reach the europium ions and give off light. The afterglow's duration is therefore set mainly by how deep the traps are, not by how slowly any single emitting state decays."},"set":{"passage":"When a glow-in-the-dark material absorbs light, some of its excited electrons end up in what physicists call a triplet state. Returning from this state to the ground state by emitting light is \"spin-forbidden,\" meaning the transition can happen only rarely, so the stored energy leaks out slowly as a faint glow. For decades, chemists assumed that making this glow last longer required finding molecules whose triplet states were even more strongly forbidden from emitting. In practice, however, the longest-lasting commercial phosphors owe little to that strategy. In these materials, the dysprosium ions create defects that trap excited electrons before they reach any emitting state at all. Heat at room temperature then releases the trapped electrons a few at a time, and only after release do they reach the europium ions and give off light. The afterglow's duration is therefore set mainly by how deep the traps are, not by how slowly any single emitting state decays."},"render_check":{"ok":true,"renderer":"std-1","checkedAt":"2026-10-20T06:07:24.245Z","issues":[]},"audit_fix":{"source":"external_audit_2026-10-13","patch":"E1019-T007","fromVersionId":"211fda92-c21d-44eb-8b79-f40fd8996fff","fromVersionNo":1}},{"patch_id":"E1019-T008","problem_id":"53d078fc-f658-4871-bbdb-f43ad359dc66","from_version_id":"2f2de544-03f3-454c-8c6c-7b0586612729","expect":{"passage":"When a strip of a viscoelastic polymer such as polyisobutylene is stretched to a fixed length and held there, the force needed to keep it stretched does not stay constant. Instead, the internal stress falls steadily over time, a phenomenon known as stress relaxation. Engineers once treated this decline as a minor nuisance to be corrected for in measurements, but materials scientist Hana Okafor argues that it is better understood as a direct record of molecular motion. In her view, the long, tangled chains that make up the polymer gradually slide past one another and untangle while the strip is held, so the stress that the chains initially bore is released bit by bit.\n\nTo test this idea, Okafor's team performed relaxation tests on the same polymer at several temperatures. If chain rearrangement drives the decline, warmer samples, whose chains move more freely, should relax faster, and the curves from different temperatures should match once time is rescaled accordingly. The results fit both predictions: stress at 60°C dropped to half its starting value in roughly a tenth of the time required at 25°C, and the rescaled curves overlapped almost perfectly.","explanation_en":"C is correct because the text presents Okafor's claim that stress relaxation records polymer chains gradually sliding and untangling, and then shows that the temperature tests matched her predictions. A borrows the older engineers' view of relaxation as a nuisance to correct, which the text sets up only to reject, and the warmer tests were never meant to remove an error. B correctly notes that chains move more freely when warm, but that is just a supporting detail, and the text never says warm polymers are unsuitable. D says the chains break, but the text describes them sliding past one another and untangling, not breaking.","explanation":"지문은 응력 이완이 고분자 사슬의 점진적 재배열을 보여 준다는 Okafor의 주장을 소개하고, 온도별 실험 결과가 그 예측과 맞았다고 설명하므로 C가 정답이다. A는 이완을 측정 오류로 본 예전 엔지니어들의 관점을 가져왔는데, 지문은 바로 그 관점을 반박하며 고온 시험은 오류를 없애는 방법이 아니었다. B의 '따뜻할수록 사슬이 자유롭다'는 지문과 맞지만 이는 근거가 되는 세부일 뿐이고, 공학적으로 쓸 수 없다는 내용은 지문에 없다. D는 사슬이 끊어진다고 하지만, 지문은 사슬이 서로 미끄러지며 풀린다고 설명한다."},"set":{"passage":"When a strip of a viscoelastic polymer such as polyisobutylene is stretched to a fixed length and held there, the force needed to keep it stretched does not stay constant. Instead, the internal stress falls steadily over time, a phenomenon known as stress relaxation. Hana Okafor argues that it is better understood as a direct record of molecular motion. In her view, the long, tangled chains that make up the polymer gradually slide past one another and untangle while the strip is held, so the stress that the chains initially bore is released.\n\nOkafor's team performed relaxation tests on the same polymer at several temperatures. If chain rearrangement drives the decline, warmer samples, whose chains move more freely, should relax faster, and the curves from different temperatures should match once time is rescaled accordingly. The results fit both predictions: stress at 60°C dropped to half its starting value in roughly a tenth of the time required at 25°C.","explanation_en":"C is correct because the text presents Okafor's claim that stress relaxation records polymer chains gradually sliding and untangling, and then shows that the temperature tests matched her predictions. A calls stress relaxation a measurement error to be removed, but the text presents it as a record of molecular motion, and the warmer tests were never meant to remove an error. B correctly notes that chains move more freely when warm, but that is just a supporting detail, and the text never says warm polymers are unsuitable. D says the chains break, but the text describes them sliding past one another and untangling, not breaking.","explanation":"지문은 응력 이완이 고분자 사슬의 점진적 재배열을 보여 준다는 Okafor의 주장을 소개하고, 온도별 실험 결과가 그 예측과 맞았다고 설명하므로 C가 정답이다. A는 이완을 없애야 할 측정 오류라고 하지만, 지문은 이를 분자 운동의 기록으로 설명하며 고온 시험도 오류를 없애려는 것이 아니었다. B의 '따뜻할수록 사슬이 자유롭다'는 지문과 맞지만 이는 근거가 되는 세부일 뿐이고, 공학적으로 쓸 수 없다는 내용은 지문에 없다. D는 사슬이 끊어진다고 하지만, 지문은 사슬이 서로 미끄러지며 풀린다고 설명한다."},"render_check":{"ok":true,"renderer":"std-1","checkedAt":"2026-10-20T06:07:24.246Z","issues":[]},"audit_fix":{"source":"external_audit_2026-10-13","patch":"E1019-T008","fromVersionId":"2f2de544-03f3-454c-8c6c-7b0586612729","fromVersionNo":1}},{"patch_id":"E1019-T009","problem_id":"b9d75f29-d9e0-4f6c-b6bd-a5c306d30f41","from_version_id":"030a6a47-6e77-4e66-a39a-67473eee2b8f","expect":{"passage":"Text 1\nIn a series of school studies, students who were praised for their effort (\"You worked hard on that\") persisted longer on difficult puzzles than students praised for their intelligence (\"You're so smart\"). Researchers argue that effort praise teaches students that ability can grow, and that this belief makes them treat setbacks as chances to learn. Because the belief comes first and the persistence follows, the researchers conclude that schools should train teachers to replace intelligence praise with effort praise.\n\nText 2\nA follow-up team tracked students who got effort praise in the same way and measured both their beliefs about ability and their persistence. Persistence rose in many students whose beliefs about ability did not change at all. Interviews pointed to something else: students read effort praise as a sign that the adult was paying close attention and expected them to keep going, and they kept going to meet that expectation. The team agrees that effort praise tends to produce more persistence than intelligence praise does."},"set":{"passage":"Text 1\nIn a series of school studies, students who were praised for their effort persisted longer on difficult puzzles than students praised for their intelligence. Researchers argue that effort praise teaches students that ability can grow, and that this belief makes them treat setbacks as chances to learn. Because the belief comes first and the persistence follows, the researchers conclude that schools should train teachers to replace intelligence praise with effort praise.\n\nText 2\nA follow-up team tracked students who got effort praise in the same way and measured both their beliefs about ability and their persistence. Persistence rose in many students whose beliefs about ability did not change. Interviews pointed to something else: students read effort praise as a sign that the adult was paying close attention and expected them to keep going, and they kept going to meet that expectation. The team agrees that effort praise tends to produce more persistence than intelligence praise does."},"render_check":{"ok":true,"renderer":"std-1","checkedAt":"2026-10-20T06:07:24.246Z","issues":[]},"audit_fix":{"source":"external_audit_2026-10-13","patch":"E1019-T009","fromVersionId":"030a6a47-6e77-4e66-a39a-67473eee2b8f","fromVersionNo":1}},{"patch_id":"E1019-T010","problem_id":"ea780ed9-ebca-4582-b16a-97b8f2be1581","from_version_id":"01732a6a-9feb-43f5-9d90-02fe26c8149a","expect":{"passage":"Graphene aerogels are among the lightest solids ever made: some samples have densities below 0.2 milligrams per cubic centimeter, lighter than the air they displace. Their structure is hierarchical, with micrometer-scale cells whose walls are themselves riddled with nanometer-scale pores. Engineers testing these materials as thermal insulators have found that heat moving through the solid graphene walls is limited mainly by how thin and sparse those walls are, and that this effect works the same way at any pore size. Heat carried by gas trapped inside the material, however, depends strongly on pore size: when pores are narrower than the average distance a gas molecule travels before striking another molecule (about 70 nanometers for air at room pressure), molecules hit pore walls more often than one another, and gas conduction drops sharply. A research team compared two aerogels of identical density, one with mostly micrometer-scale pores and one in which most of the volume consisted of pores smaller than 50 nanometers. Based on these findings, the team should expect that ______"},"set":{"passage":"Graphene aerogels are among the lightest solids ever made: some samples have densities below 0.2 milligrams per cubic centimeter, lighter than the air they displace. Engineers testing these materials as thermal insulators have found that heat moving through the solid graphene walls is limited mainly by how thin and sparse those walls are, and that this effect works the same way at any pore size. Heat carried by gas trapped inside the material, however, depends strongly on pore size: when pores are narrower than the average distance a gas molecule travels before striking another molecule (about 70 nanometers for air at room pressure), molecules hit pore walls more often than one another, and gas conduction drops sharply. A research team compared two aerogels of identical density, one with mostly micrometer-scale pores and one in which most of the volume consisted of pores smaller than 50 nanometers. Based on these findings, the team should expect that ______"},"render_check":{"ok":true,"renderer":"std-1","checkedAt":"2026-10-20T06:07:24.247Z","issues":[]},"audit_fix":{"source":"external_audit_2026-10-13","patch":"E1019-T010","fromVersionId":"01732a6a-9feb-43f5-9d90-02fe26c8149a","fromVersionNo":1}}],"sets":[]}$audit_plan$::jsonb;
  v_actor uuid := (select id from profiles where role = 'admin' order by created_at limit 1);
  u jsonb; s jsonb; a jsonb;
  v_prob problems%rowtype; v_cur problem_versions%rowtype; v_have jsonb; v_want jsonb; v_new uuid;
  v_src mock_exam_sets%rowtype; v_new_set uuid; v_cols text; v_cols_i text; v_pids uuid[];
  v_n int; v_stale int; v_bad text; v_done_p int := 0; v_skip_p int := 0; v_done_s int := 0; v_skip_s int := 0;
begin
  if v_actor is null then raise exception 'No admin profile found.'; end if;

  -- Phase 1: problems -> new published problem version each (same flow as the admin problem editor)
  for u in select * from jsonb_array_elements(v_plan->'problems') loop
    select * into v_prob from problems where id = (u->>'problem_id')::uuid;
    if v_prob.id is null then raise exception '[%] problem % not found', u->>'patch_id', u->>'problem_id'; end if;
    select * into v_cur from problem_versions where id = v_prob.published_version_id;
    if v_cur.id is null then raise exception '[%] problem % has no published version', u->>'patch_id', v_prob.id; end if;
    -- final field values = current published version, overridden by the planned new values
    a := jsonb_build_object('passage', v_cur.passage, 'question', v_cur.question, 'options', v_cur.options, 'correct_index', v_cur.correct_index, 'answers', v_cur.answers,
                            'explanation', v_cur.explanation, 'explanation_en', v_cur.explanation_en, 'figure', v_cur.figure, 'statements', v_cur.statements, 'difficulty', v_cur.difficulty,
                            'figure_checked', coalesce(v_cur.figure_checked, false), 'evidence_target', v_cur.evidence_target, 'evidence_span', v_cur.evidence_span,
                            'answer_rationale', v_cur.answer_rationale, 'distractor_error_types', v_cur.distractor_error_types);
    v_have := (select coalesce(jsonb_object_agg(k, a->k), '{}'::jsonb) from jsonb_object_keys(u->'expect') k);
    v_want := (select coalesce(jsonb_object_agg(k, (a || (u->'set'))->k), '{}'::jsonb) from jsonb_object_keys(u->'expect') k);
    if v_have = v_want then v_skip_p := v_skip_p + 1; raise notice '[%] already applied, skipped', u->>'patch_id'; continue; end if;
    if v_have <> u->'expect' then raise exception '[%] DRIFT: the published version of problem % no longer matches the expected old content (re-run the dry-run)', u->>'patch_id', v_prob.id; end if;
    a := a || (u->'set');
    if exists (select 1 from problem_versions where problem_id = v_prob.id and status in ('draft', 'in_review')) then
      raise exception '[%] problem % has an open draft/in_review version', u->>'patch_id', v_prob.id;
    end if;
    v_new := public.save_problem_draft_version(
      p_problem_id => v_prob.id, p_passage => a->>'passage', p_options => nullif(a->'options', 'null'::jsonb), p_correct_index => (a->>'correct_index')::int,
      p_explanation => a->>'explanation', p_difficulty => a->>'difficulty', p_actor_id => v_actor, p_answers => nullif(a->'answers', 'null'::jsonb),
      p_figure => nullif(a->'figure', 'null'::jsonb), p_figure_checked => coalesce((a->>'figure_checked')::boolean, false), p_statements => nullif(a->'statements', 'null'::jsonb),
      p_question => a->>'question', p_repair_status => null, p_explanation_en => a->>'explanation_en', p_evidence_target => a->>'evidence_target',
      p_evidence_span => a->>'evidence_span', p_answer_rationale => a->>'answer_rationale', p_distractor_error_types => nullif(a->'distractor_error_types', 'null'::jsonb));
    perform public.set_problem_render_check(v_new, u->'render_check');
    perform public.set_problem_quality(v_new, coalesce(v_cur.quality, '{}'::jsonb) || jsonb_build_object('auditFix', u->'audit_fix'));
    perform public.confirm_and_publish_problem_version(v_new, v_actor);
    if u ? 'ap' then perform public.ap_attach_new_version(u->'ap'->>'candidate_key', (u->'ap'->>'item_index')::int, v_new, v_actor); end if;
    v_done_p := v_done_p + 1;
    raise notice '[%] problem % -> new version %', u->>'patch_id', v_prob.id, v_new;
  end loop;

  -- Phase 2: sets -> new set version per affected published set (items of the patched problems point to the new problem versions; snapshots of the rest are copied)
  for s in select * from jsonb_array_elements(v_plan->'sets') loop
    select array_agg(x::uuid) into v_pids from jsonb_array_elements_text(s->'problem_ids') x;
    select * into v_src from mock_exam_sets where set_group_id = (s->>'set_group_id')::uuid and status = 'published' and archived_at is null order by version_no desc limit 1 for update;
    if v_src.id is null then raise exception 'Set group % has no published version (%).', s->>'set_group_id', s->>'name'; end if;
    select count(*) into v_n from mock_exam_set_items i where i.exam_set_id = v_src.id and i.problem_id = any (v_pids);
    if v_n <> cardinality(v_pids) then raise exception 'Set % v% holds % of % target problems.', v_src.name, v_src.version_no, v_n, cardinality(v_pids); end if;
    select count(*) into v_stale from mock_exam_set_items i join problems p on p.id = i.problem_id
     where i.exam_set_id = v_src.id and i.problem_id = any (v_pids) and p.published_version_id is distinct from i.problem_version_id;
    if v_stale = 0 then v_skip_s := v_skip_s + 1; raise notice 'set % v% already up to date, skipped', v_src.name, v_src.version_no; continue; end if;
    perform pg_advisory_xact_lock(hashtextextended('mock_exam_new_version:' || v_src.set_group_id::text, 0));
    if exists (select 1 from mock_exam_sets where set_group_id = v_src.set_group_id and status = 'draft') then
      raise exception 'A draft version already exists for set % - publish or archive it first.', v_src.name;
    end if;
    v_new_set := gen_random_uuid();
    select string_agg(quote_ident(column_name), ', ' order by ordinal_position) into v_cols
      from information_schema.columns where table_schema = 'public' and table_name = 'mock_exam_sets' and is_generated = 'NEVER'
       and column_name not in ('id', 'version_no', 'status', 'created_by', 'created_at', 'published_at', 'published_by', 'archived_at', 'access_tier');
    execute format('insert into mock_exam_sets (id, version_no, status, created_by, access_tier, %s) select $1, $2, ''draft'', $3, ''tutoring'', %s from mock_exam_sets where id = $4', v_cols, v_cols)
      using v_new_set, (select max(version_no) + 1 from mock_exam_sets where set_group_id = v_src.set_group_id), v_actor, v_src.id;
    select string_agg(quote_ident(column_name), ', ' order by ordinal_position),
           string_agg(case column_name
                        when 'problem_version_id' then 'case when i.problem_id = any ($3) then coalesce(p.published_version_id, i.problem_version_id) else i.problem_version_id end'
                        when 'content_snapshot' then 'case when i.problem_id = any ($3) then null else i.content_snapshot end'
                        else 'i.' || quote_ident(column_name) end, ', ' order by ordinal_position)
      into v_cols, v_cols_i
      from information_schema.columns where table_schema = 'public' and table_name = 'mock_exam_set_items' and is_generated = 'NEVER' and column_name not in ('id', 'exam_set_id', 'created_at');
    execute format('insert into mock_exam_set_items (exam_set_id, %s) select $1, %s from mock_exam_set_items i join problems p on p.id = i.problem_id where i.exam_set_id = $2', v_cols, v_cols_i)
      using v_new_set, v_src.id, v_pids;
    if v_src.format = 'mst' and not coalesce((public.mock_exam_validate_mst_set(v_new_set)->>'ready')::boolean, false) then
      raise exception 'New version of % is not ready (4-module blueprint check failed).', v_src.name;
    end if;
    select string_agg(x.problem_id::text || ':' || x.issue, ', ') into v_bad from (select * from public.mock_exam_set_item_issues(v_new_set) where issue is not null limit 5) x;
    if v_bad is not null then raise exception 'New version of % has item issues: %', v_src.name, v_bad; end if;
    perform public.mock_exam_publish_set(v_new_set, v_actor);
    v_done_s := v_done_s + 1;
    raise notice 'set % v% -> v% (%)', v_src.name, v_src.version_no, v_src.version_no + 1, v_new_set;
  end loop;
  raise notice 'DONE problems applied=% skipped=%; sets applied=% skipped=%', v_done_p, v_skip_p, v_done_s, v_skip_s;
end
$audit$;
